'use strict';
// Local-only delivery state. A completed share promise is a handoff, not proof of saving.
(function(root){
 const BUILD='2026-11-22-delivery-2';
 function create({document:doc=root.document,navigator:nav=root.navigator,window:win=root,onReport=()=>{}}={}){
  const get=id=>doc.getElementById(id);let file=null,url='',report=null,sharing=false;
  function capabilities(){return{secureContext:!!win.isSecureContext,share:typeof nav.share==='function',canShare:typeof nav.canShare==='function',file:typeof win.File==='function',videoEncoder:typeof win.VideoEncoder, audioEncoder:typeof win.AudioEncoder,mediaRecorder:typeof win.MediaRecorder,standalone:!!win.matchMedia?.('(display-mode: standalone)').matches,userActivation:nav.userActivation?.isActive??null}}
  function refresh(){if(!report)return;get('exportDiagnosticText').value=JSON.stringify(report,null,2);get('exportDiagnosticSummary').textContent='Engine: '+(report.engine||'pending')+' · Blob: '+(report.blob?report.blob.bytes+' bytes / '+report.blob.type:'pending')+' · Stage: '+report.stage;onReport(report)}
  function event(stage,detail={}){if(!report)return;report.stage=stage;if(stage==='encoder-selected')report.engine=detail.engine;if(stage==='blob-created')report.blob={...detail};if(stage==='inspection-passed')report.verified={...detail};report.events.push({at:new Date().toISOString(),elapsedMs:Math.round(performance.now()-report.startedAt),stage,...detail});if(report.events.length>100)report.events.splice(1,1);refresh()}
  function message(text){get('exportDeliveryStatus').textContent=text}
  function reset(request){file=null;url='';sharing=false;get('exportShare').disabled=false;get('exportShare').hidden=true;get('exportViewer').hidden=true;get('exportDeliveryStatus').hidden=false;message('بعد اكتمال التصدير سيظهر زر حفظ أو مشاركة الفيديو هنا. لا تخرج من التطبيق.');get('exportDiagnosticPanel').hidden=false;get('exportDiagnostics').hidden=false;report={app:BUILD,createdAt:new Date().toISOString(),startedAt:performance.now(),capabilities:capabilities(),request,stage:'starting',events:[]};event('starting')}
  function ready(blob,objectUrl,name){url=objectUrl;try{file=new win.File([blob],name,{type:blob.type.split(';')[0]||'video/mp4'});event('file-created',{bytes:file.size,type:file.type,name:file.name})}catch(error){event('file-unavailable',{name:error.name,message:String(error.message)})}
   let supported=false;try{supported=!!file&&typeof nav.share==='function'&&!!nav.canShare?.({files:[file]})}catch(error){event('file-share-check-error',{name:error.name,message:String(error.message)})}
   get('exportShare').hidden=!supported;const viewer=get('exportViewer');viewer.href=url;viewer.hidden=false;event('delivery-ready',{fileSharing:supported,blobBytes:blob.size,blobType:blob.type});message(supported?'الفيديو جاهز. اضغط «حفظ أو مشاركة الفيديو» لفتح قائمة الجهاز، ثم اختر حفظ الفيديو أو حفظ في الملفات. لن تفتح القائمة تلقائيًا بعد انتهاء العدّ.':'الفيديو جاهز. اضغط تنزيل الفيديو. إذا لم يظهر التنزيل، اضغط فتح الفيديو في نافذة للحفظ ثم استخدم مشاركة المتصفح للحفظ في الملفات.');
  }
  // Invoke share synchronously inside the NEW click, before any await loses activation.
  get('exportShare').onclick=()=>{if(!file||sharing)return;sharing=true;get('exportShare').disabled=true;event('share-requested',{userActivation:nav.userActivation?.isActive??null});let promise;try{promise=nav.share({files:[file]})}catch(error){failed(error);return}Promise.resolve(promise).then(()=>{event('share-resolved');message('عاد طلب المشاركة بدون خطأ. تأكد من حفظ الفيديو في الصور أو الملفات؛ التطبيق لا يستطيع تأكيد مكان الحفظ.');}).catch(failed).finally(()=>{sharing=false;get('exportShare').disabled=false})};
  function failed(error){sharing=false;get('exportShare').disabled=false;event(error.name==='AbortError'?'share-cancelled':'share-failed',{name:error.name||'Error',message:String(error.message||error)});message(error.name==='AbortError'?'أُلغيت المشاركة أو لا يوجد هدف متاح. الفيديو ما زال جاهزًا: أعد المحاولة أو افتحه في نافذة للحفظ.':'تعذّر فتح المشاركة. جرّب الزر مرة أخرى، أو افتح الفيديو في نافذة للحفظ واستخدم مشاركة المتصفح. صوّر سجل التصدير أدناه إذا استمرت المشكلة.')}
  get('exportViewer').onclick=()=>{event('viewer-link-clicked',{userActivation:nav.userActivation?.isActive??null});message('فتح الفيديو في نافذة جديدة مطلوب. من نافذة الفيديو استخدم مشاركة ثم حفظ الفيديو أو حفظ في الملفات. إذا لم تفتح، اسمح بالنافذة أو استخدم معاينة الفيديو هنا. لا يمكن للتطبيق تأكيد الحفظ.');};
  for(const id of ['download','exportDownload'])get(id).addEventListener('click',()=>{event('download-link-clicked',{userActivation:nav.userActivation?.isActive??null});message('تم طلب التنزيل من المتصفح، وليس تأكيد الحفظ. إذا لم يظهر ملف، استخدم حفظ أو مشاركة الفيديو، أو فتح الفيديو في نافذة للحفظ.');});
  const preview=get('exportPreview');for(const name of ['loadedmetadata','canplay','error'])preview.addEventListener(name,()=>event('preview-'+name,name==='error'?{code:preview.error?.code,message:preview.error?.message}:{width:preview.videoWidth,height:preview.videoHeight}));
  get('exportCopyDiagnostics').onclick=async()=>{try{await nav.clipboard.writeText(get('exportDiagnosticText').value);get('exportCopyStatus').textContent='تم نسخ السجل، بدون صور أو صوت.'}catch{get('exportDiagnosticText').focus();get('exportDiagnosticText').select();get('exportCopyStatus').textContent='حدد النص وانسخه، أو صوّر هذا السجل.'}};
  return{reset,event,ready,report:()=>report};
 }
 root.RasmDelivery=Object.freeze({create,BUILD});
})(typeof window!=='undefined'?window:globalThis);
